@page "/settings"
@using sv_d3bf73d2d7b1451ca8b19fbf6b8f38e7.Services
@rendermode InteractiveServer
@implements IDisposable
@inject ThemeService ThemeService

<PageTitle>Settings</PageTitle>

<h3>User Preferences</h3>

<div class="card p-4" style="max-width: 400px; border-color: @ThemeService.AccentColor;">
    <div class="mb-3">
        <label class="form-label">Theme</label>
        <select class="form-select" @bind="selectedTheme">
            @foreach (var mode in Enum.GetValues<ThemeMode>())
            {
                <option value="@mode">@mode</option>
            }
        </select>
    </div>

    <div class="mb-3">
        <label class="form-label">Accent Color</label>
        <input type="color" class="form-control form-control-color"
               @bind="selectedColor" />
    </div>

    <button class="btn btn-primary" @onclick="Save"
            style="background-color: @ThemeService.AccentColor; border-color: @ThemeService.AccentColor;">
        Save Preferences
    </button>
</div>

<p class="mt-3 text-muted">
    Current: <strong>@ThemeService.Theme</strong> / <span style="color: @ThemeService.AccentColor;">@ThemeService.AccentColor</span>
</p>

@code {
    private ThemeMode selectedTheme;
    private string selectedColor = "#0d6efd";

    protected override void OnInitialized()
    {
        selectedTheme = ThemeService.Theme;
        selectedColor = ThemeService.AccentColor;
        ThemeService.OnChange += OnThemeChanged;
    }

    private void Save()
    {
        ThemeService.SetPreferences(selectedTheme, selectedColor);
    }

    private void OnThemeChanged()
    {
        selectedTheme = ThemeService.Theme;
        selectedColor = ThemeService.AccentColor;
        InvokeAsync(StateHasChanged);
    }

    public void Dispose()
    {
        ThemeService.OnChange -= OnThemeChanged;
    }
}

